theorem integral_partial_derivative_eq_zero [NormedSpace ℝ E] {n : ℕ}
    (e : E ≃L[ℝ] (Fin (n + 1) → ℝ)) {ν : Measure E}
    (he : MeasurePreserving e ν volume) (i : Fin (n + 1))
    {f : E → ℝ} {df : E → E →L[ℝ] ℝ}
    (hf : Integrable f ν)
    (hg : Integrable (fun x => df x (e.symm (Pi.single i 1))) ν)
    (hd : ∀ x, HasFDerivAt f (df x) x) :
    ∫ x, df x (e.symm (Pi.single i 1)) ∂ν = 0

theorem convolutionLogHeatFlow_gradient_sq_le {f : E → ℝ}
    (hf : Integrable f) (hf0 : ∀ z, 0 ≤ f z) (hmass : 0 < ∫ z, f z) {R : ℝ}
    (hsupport : ∀ z, f z ≠ 0 → ‖z‖ ≤ R) {t : ℝ} (ht : 0 < t) (x : E) :
    ‖(convolutionLogHeatFlow hf hf0 hmass).gradient t x‖^2 ≤
      convolutionGrowthCoefficient R t*(1+‖x‖^2)

theorem convolutionLogHeatFlow_hessian_le_growth {f : E → ℝ}
    (hf : Integrable f) (hf0 : ∀ z, 0 ≤ f z) (hmass : 0 < ∫ z, f z) {R : ℝ}
    (hsupport : ∀ z, f z ≠ 0 → ‖z‖ ≤ R) {t : ℝ} (ht : 0 < t) (x : E) :
    ‖(convolutionLogHeatFlow hf hf0 hmass).hessian t x‖ ≤
      convolutionGrowthCoefficient R t*(1+‖x‖^2)

theorem logarithmicHessian_norm_le {u C K : ℝ} {g : E} {H : E →L[ℝ] E}
    (hu : 0 < u) (hg : ‖g‖ ≤ C*u) (hH : ‖H‖ ≤ K*u) :
    ‖logarithmicHessian u g H‖ ≤ K + C^2

theorem gaussianConvolutionGradient_norm_le_of_support_bound {f : E → ℝ}
    (hf : Integrable f) (hf0 : ∀ z, 0 ≤ f z) {R : ℝ}
    (hsupport : ∀ z, f z ≠ 0 → ‖z‖ ≤ R) {b : ℝ} (hb : 0 < b) (x : E) :
    ‖gaussianConvolutionGradient b f x‖ ≤
      (2*b*(‖x‖+R))*gaussianConvolution b f x

theorem gaussianConvolutionHessian_norm_le_of_support_bound {f : E → ℝ}
    (hf : Integrable f) (hf0 : ∀ z, 0 ≤ f z) {R : ℝ}
    (hsupport : ∀ z, f z ≠ 0 → ‖z‖ ≤ R) {b : ℝ} (hb : 0 < b) (x : E) :
    ‖gaussianConvolutionHessian b f x‖ ≤
      (2*b+4*b^2*(‖x‖+R)^2)*gaussianConvolution b f x

theorem heatConvolutionGradient_norm_le_of_support_bound {f : E → ℝ}
