theorem le_of_heat_limits (H : D.HeatIntegrability U) {a b : ℝ}
    (hzero : Tendsto (fun t => ∫ x, D.heatProduct U t x) (𝓝[>] 0) (𝓝 a))
    (hinfty : Tendsto (fun t => ∫ x, D.heatProduct U t x) atTop (𝓝 b)) : a ≤ b

theorem rescaledProduct_le {R : ι → ℝ}
    (hsupport : ∀ i z, f i z ≠ 0 → ‖z‖ ≤ R i) {e : ℝ} (he : |e| ≤ 1) (x : E) :
    D.rescaledProduct f e x ≤ D.convolutionAmplitude f R 1*Real.exp (-(1/8 : ℝ)*‖x‖^2)

theorem integral_rescaledProduct_continuousAt_zero {R : ι → ℝ}
    (hsupport : ∀ i z, f i z ≠ 0 → ‖z‖ ≤ R i) :
    ContinuousAt (fun e => ∫ x, D.rescaledProduct f e x) 0

theorem integral_prod_heatConvolution_monotoneOn {R : ι → ℝ}
    (hsupport : ∀ i z, f i z ≠ 0 → ‖z‖ ≤ R i) :
    MonotoneOn (fun t => ∫ x, ∏ i, (heatConvolution (f i) t (D.map i x)) ^ D.weight i) (Ioi 0)

theorem convolutionLogHeatFlow_logValue_le {f : E → ℝ}
    (hf : Integrable f) (hf0 : ∀ z, 0 ≤ f z) (hmass : 0 < ∫ z, f z) {R : ℝ}
    (hsupport : ∀ z, f z ≠ 0 → ‖z‖ ≤ R) {t : ℝ} (ht : 0 < t) (x : E) :
    (convolutionLogHeatFlow hf hf0 hmass).logValue t x ≤
      convolutionLogAmplitude f R t - ((4*t)⁻¹/2)*‖x‖^2

theorem convolutionLogHeatFlow_hessian_continuous {f : E → ℝ}
    (hf : Integrable f) (hf0 : ∀ z, 0 ≤ f z) (hmass : 0 < ∫ z, f z)
    {t : ℝ} (ht : 0 < t) : Continuous ((convolutionLogHeatFlow hf hf0 hmass).hessian t)
